INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('All 26 winners of this year’s community and council awards named', 'all-26-winners-of-this-years-community-and-council-awards-named', '<p>Helen and 25 others were among the winners at the Community and Council Awards 2026 held in Dublin on February 28. Helen had been nominated by Limerick City and County Council for her leadership and service to community development and environmental action over many years.</p>
<p><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2026/03/Helen-ODonnell-from-Limerick-was-announced-as-the-Volunteer-of-the-Year-at-the-LAMA-Community-and-Council-Awards-2026.jpg" alt="" width="1592" height="956" /></p>
<p>The awards, now in their 20th year, are organised by the Local Authorities Members Association, to recognise exceptional local authority projects, partnerships, and community champions.</p>
<p>Councillors nominate people and projects for the awards and, this year, the organisers received 533 nominations and shortlisted 137 entries across 26 categories.</p>
<p><figure aria-describedby="caption-attachment-256162"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2026/03/LAMA_514-scaled-1.jpeg" alt="" width="1707" height="2560" /><figcaption><em>• Kilkenny County Council won two main awards and were shortlisted in at least four other categories.</em></figcaption></figure></p>
<p>&#8220;The people and projects recognised tonight reflect the resilience, creativity, and volunteer spirit that strengthen local democracy and improve quality of life for people nationwide,” said John Hogan, Chairman of IPB Insurance, the awards’ long term sponsor and partner.</p>
<p><figure aria-describedby="caption-attachment-256153"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2026/03/LAMA_342-scaled-1.jpeg" alt="" width="2560" height="1380" /><figcaption><em>• Waterford City and County Council won an award for Best Green Sustainable Initiative &#8211; shown above.</em></figcaption></figure></p>
<p><strong>The winners are:</strong></p>
<p><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2026/03/LAMA-award-winners-2026-1.png" alt="" width="913" height="800" /> <img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2026/03/LAMA-award-winners-2026-2.png" alt="" width="915" height="724" /></p>
<p>In addition to these winners, a Grand Prix Award went to Dun Laoghaire-Rathdown County Council and a Lifetime Achievement Award was presented to Tom Dowling. Tom served as CEO of <a tabindex="0" href="https://www.linkedin.com/company/meath-county-council/" target="_self">Meath County Council</a> and <a tabindex="0" href="https://www.linkedin.com/company/carlowcountycouncil/" target="_self">Carlow County Council</a> and is the founder and chair of <a tabindex="0" href="https://www.linkedin.com/company/co-operation-ireland/" target="_self">Co-operation Ireland</a>’s Pride of Place Awards, established in 2003.</p>', 'This year’s Council of the Year Award went to South Dublin County Council, while Helen O’Donnell from Limerick was named as Community Volunteer of the Year. We have all the award winners here!', 'https://changingireland.ie/wp-content/uploads/2026/03/LAMA-award-winners-2026-2.png', '', '[{"slug":"community","title":"Community"}]', '[{"slug":"local-authorities-members-awards","title":"Local Authorities Members Awards"},{"slug":"volunteering","title":"volunteering"}]', '', 256152, 1, '2026-03-20T15:25:56Z', '2026-06-25T11:52:51Z', '2026-03-20T15:25:56Z')
