INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Colourful launch by Southside Partnership of their new strategic plan', 'colourful-launch-by-southside-partnership-of-their-new-strategic-plan', '<p>The plan itself sets out an ambitious strategic vision that can also respond to emerging needs as they arise. It was formally launched by <strong>An Cathaoirleach, Cllr. Jim Gildea,</strong> with the event drawing a large attendance from stakeholders in the area.</p>
<p>“The plan is focused on building resilient, inclusive, sustainable and thriving communities across Dún Laoghaire Rathdown,” said the organisation in a statement.</p>
<p>Speaking after the launch <strong>Sinéad Sherwin, CEO,</strong> said, &#8220;After almost 30-years of working in partnership with local communities and key strategic partners to develop collaborative responses promoting social inclusion, our new strategic plan clearly represents our commitment to empowering those individuals and communities we care most about.”</p>
<p><figure aria-describedby="caption-attachment-256144"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2026/03/Strategic-Plan-Launch-An-Cathaoirleach-group-scaled-1.jpg" alt="" width="2560" height="1707" /><figcaption><em>• Pictured (l to r): Gogontle Morula, Finance Manager, Southside Partnership; Finn McGuirk, Enterprise and Employment Programme Manager, Southside Partnership; An Cathaoirleach Cllr. Jim Gildea; Sinéad Sherwin, CEO Southside Partnership; Sandra King, Social Inclusion Manager, Southside Partnership; Alan Wyley, chairperson of Southside Partnership. Photo: Dave Keegan Photography.</em></figcaption></figure></p>
<p>The plan outlines key priorities for the coming years, including:</p>
<ul>
<li>Investing in evidence-informed early interventions for children, young people and families.</li>
<li>Placing a greater emphasis on arts and culture as a method for deepening community cohesion and participation.</li>
<li>Expanding employment, training, enterprise and social enterprise supports.</li>
<li>Embedding a culture of sustainability into the heart of the work, ensuring programmes and services actively support long-term well-being, resource stewardship, and equitable opportunity.</li>
</ul>
<p><figure aria-describedby="caption-attachment-256145"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2026/03/Entertainers-from-LBS-LoughlinstownBallybrack-and-Shanganagh-Mens-Shed-at-Southside-Partnerships-launch-of-their-Strategic-Plan-scaled-1.jpg" alt="" width="2560" height="1709" /><figcaption><em>• Entertainers from LBS (Loughlinstown, Ballybrack and Shanganagh) Men&#8217;s Shed at Southside Partnership&#8217;s launch of their Strategic Plan. Photo: Dave Keegan.</em></figcaption></figure></p>
<p>Southside Partnership&#8217;s work is funded through the Social Inclusion and Community Activation Programme (SICAP) 2024–2028, as well as Community Employment and Tús Schemes supported by the Department of Social Protection. It also manages a number of projects financed through the HSE, Tusla, local government and philanthropy.</p>
<p>The Partnership works through collaboration, advocacy, and responsive, person-centred programmes, with and within local communities, to advance social, cultural and economic inclusion, strengthen local resilience, and create pathways for people to realise their potential.</p>
<p>At the launch the organisation highlighted its commitment to transparent implementation, delivering person-centred supports that empower local groups, strengthen partnerships, and invest in its people and systems to ensure long-term sustainability.</p>
<p>The plan can be downloaded from: <a href="http://www.southsidepartnership.ie">www.southsidepartnership.ie</a></p>', 'You’ve been probably been to a few lame launches where the highlight is a Powerpoint presentation. They do it differently in south Dublin. On March 7, amidst a blaze of colour, music and dance, Southside Partnership, which operates in the Dún Laoghaire–Rathdown area, launched its new 5-year Strategic Plan titled ‘Strengthening Foundations, Expanding Possibilities’.', 'https://changingireland.ie/wp-content/uploads/2026/03/Dancers-from-The-Zoryanna-dance-group-at-the-launch-of-Southside-Partnerships-Srategic-Plan-scaled-1.jpg', '', '[{"slug":"planning-governance","title":"Planning & Governance"}]', '[]', '', 257722, 1, '2026-03-12T14:17:14Z', '2026-06-25T11:53:15Z', '2026-03-12T14:17:14Z')
