INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Refugees including kids at risk in emergency accommodation – Doras report', 'refugees-including-kids-at-risk-in-emergency-accommodation-doras-report', '<p>It says that “lasting harm” is caused to people by “prolonged congregated living in Ireland’s international protection system”.<br />
The 170-page report by support group Doras compares living conditions for asylum-seekers in permanent accommodation with the experiences of those who are placed in emergency accommodation.</p>
<p>As Doras also says, “While permanent centres have faced scrutiny in recent years, emergency accommodation, which now houses the majority of international protection applicants, remains largely unexamined, weakly regulated, and without independent oversight.”</p>
<p>“Emergency accommodation was meant to be temporary,” it points out, calling for reform and for full inspections, national standards, and for all asylum-seeker accommodation “to operate within a social care framework”.</p>
<p>“Children seeking safety deserve space to grow, and families and individuals deserve a chance to thrive,” says Doras.</p>
<p>Since the report was published <a href="https://www.rte.ie/news/ireland/2026/0311/1562694-tusla-children-accommodation/">RTE has highlighted</a> how last year more than 1,100 children in Tusla&#8217;s care were placed in unregulated emergency accommodation such as hotels and short-term rentals. A large number of these children are asylum-seekers who came to Ireland seeking refuge.</p>
<p>You can download Doras&#8217;s &#8216;The Reception Gap&#8217; summary report and full report from: <a href="https://doras.org/publications/reception-gap-permanent-international-protection-accommodation-versus-emergency">https://doras.org/publications/reception-gap-permanent-international-protection-accommodation-versus-emergency</a></p>', 'A new report called ‘The Reception Gap’ raises concerns for people in living in state-provided emergency accommodation, giving a voice to residents about the conditions and lack of oversight.', 'https://changingireland.ie/wp-content/uploads/2026/03/Doras-report-The-Reception-Gap.png', '', '[{"slug":"refugees-ukraine","title":"Refugees/Ukraine"}]', '[]', '', 257720, 1, '2026-03-12T13:02:31Z', '2026-07-01T17:31:44Z', '2026-03-12T13:02:31Z')
