INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Organisers surprised at numbers that attended Limerick Jobs Expo with a difference', 'organisers-surprised-at-numbers-that-attended-limerick-jobs-expo-with-a-difference', '<p>It aimed to connect people who encounter barriers and discrimination with supportive employers. People who have served time in prison encounter more obstacles than most and the event was designed to encourage them – among others &#8211; and it showed people real pathways to employment.<br />
Advice was provided by staff and volunteers from Bedford Row Family Project and Northside Family Resource Centre, and by officials from the Departments of Social Protection and the Department of Justice. Also central to the event was the voluntary campaigning, training and support group Spéire Nua.<br />
It is likely that this event, when next held, will attract even more community groups and employers and people who struggle to find work for a variety of reasons.</p>
<p>View these video interviews on our YouTube channel and find out more about the event and the supports that are there that people can tap into today:</p>
<div><iframe title="Organisers surprised at numbers that attended Limerick Jobs Expo with a difference" width="696" height="392" src="https://www.youtube.com/embed/EZVcvF7C1VY?start=4&amp;feature=oembed" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div>', 'Even the organisers were surprised at the number of people who showed up for a Jobs Expo with a difference that was held in City Hall, Limerick, on March 5. Organisers recorded 178 visitors to the event, the first of its kind held outside Dublin.', 'https://changingireland.ie/wp-content/uploads/2026/03/IMG_8030-scaled-1.jpg', '', '[{"slug":"income-employment","title":"Income & Employment"}]', '[]', '', 257718, 1, '2026-03-10T12:08:27Z', '2026-06-25T11:54:12Z', '2026-03-10T12:08:27Z')
