INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Near FM’s Northside Today discusses Dubs in Changing Ireland', 'near-fms-northside-today-discusses-dubs-in-changing-ireland', '<p>Listen back: <a href="https://listenagain.org/?p=59493">https://listenagain.org/?p=59493</a></p>
<p>The interview, over 20 minutes, looked at the magazine&#8217;s history and its current edition and stories relevant to Dublin readers and to anyone interested in community development.</p>
<p>The Near FM discussion looked at the arguments made by youth worker and famous boxer, Craig O&#8217;Brien, who as part of his work with the <a href="https://solasproject.com/">Solas Project</a> has launched a <a href="https://changingireland.ie/solas-community-worker-craig-obrien-is-fighting-for-change-in-d8/">“Fighting For Change” programme targeted at young people in Dublin 8</a>. The challenges are enormous, yet Craig and his team in the Solas project are reaching as many youths as they can.</p>
<p><a href="https://changingireland.ie/solas-community-worker-craig-obrien-is-fighting-for-change-in-d8/">https://changingireland.ie/solas-community-worker-craig-obrien-is-fighting-for-change-in-d8/</a></p>
<p>Craig happens to be the third Dub in the past 12 months to feature <a href="https://changingireland.ie/wp-content/uploads/2026/01/Issue-91-Winter-2025-Changing-Ireland-28p.pdf">on the front cover</a> – the others being singer <a href="https://changingireland.ie/wp-content/uploads/2025/12/Issue-90-Autumn-2025-Changing-Ireland-32p.pdf">Gemma Dunleavy</a> and enterprise centre co-ordinator <a href="https://changingireland.ie/wp-content/uploads/2025/05/Issue-88-Spring-2025-Changing-Ireland-32p.pdf">Evanne Kilmurray</a>.</p>
<p><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2026/02/IMG_2085-scaled-1.jpeg" alt="" width="1920" height="2560" /></p>
<p>Philip asked if people can write in with story ideas and suggestions. Allen said that was how many of our stories originate and he encouraged Philip and others to email (<a href="mailto:editor@changingireland.ie">editor@changingireland.ie</a>).</p>
<p>The radio show also looked some outstanding stories. For example, from Dublin we had a recent story describing the difficulties facing Tus participants who cannot open bank accounts, preventing them from taking up Tus placements, thereby losing out on potentially life-changing opportunities.</p>
<p>Philip urged people to read the magazine online or sign up to receive it by post. Again, email: <a href="mailto:editor@changingireland.ie">editor@changingireland.ie</a> or contact us via social media with your details.</p>', 'Near FM, probably the country’s best established community radio station, covering Northside Dublin, today interviewed Changing Ireland editor Allen Meagher. You can listen back to the show here.', 'https://changingireland.ie/wp-content/uploads/2026/02/Near-FM-radio-station-in-Northside-Dublin-today-interviewed-Changing-Ireland-editor-Allen-Meagher-e1771523771838.png', '', '[{"slug":"editorial","title":"Editorial"}]', '[{"slug":"allen-meagher","title":"Allen Meagher"},{"slug":"community-development","title":"community development"},{"slug":"community-radio","title":"community radio"},{"slug":"craig-obrien","title":"Craig O''Brien"},{"slug":"dublin","title":"Dublin"},{"slug":"nearfm","title":"NearFM"},{"slug":"philip-smith","title":"Philip Smith"}]', '', 257717, 1, '2026-02-19T17:51:07Z', '2026-06-25T11:54:27Z', '2026-02-19T17:51:07Z')
