INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Is Changing Ireland in your local library? Yes!', 'is-changing-ireland-in-your-local-library-yes', '<div>We dropped into <a href="https://www.facebook.com/WHCCommunityLibrary/">our local library in Watch House Cross</a>, Moyross, curious to see for ourselves where it was shelved. Imagine our delight to find the latest edition on show right at the front entrance for all to see!</div>
<div>As editor Allen Meagher notes:</div>
<blockquote>
<div>&#8220;Every library also has a back catalogue going back over many years &#8211; great for students, researchers and aspiring community activists.</div>
<div>“Libraries today, of course, are fantastic community hubs. They have grown and expanded in ways we never imagined when we lived in fear of being fined for late returns. Nowadays, libraries are at the heart of community development, welcoming all and regularly hosting events.</div>
<div>&#8220;We are grateful to all the county librarians who help us to distribute Changing Ireland through their nationwide network,” he added.</div>
</blockquote>
<div>
<p><iframe title="Changing Ireland is available in 310 public libraries across Ireland!!" width="696" height="392" src="https://www.youtube.com/embed/iqm1lB0MHfg?feature=oembed" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></p>
</div>
<div></div>
<div>You will also find Changing Ireland in community centres, family resource centres, local development companies, prison education units, enterprise centres and in the Dáil and Seanad &#8211; among other places.</div>
<div></div>
<div>And all 25 years of our magazine are freely available here on this website at: <a href="https://changingireland.ie/digital-magazine-archive/">https://changingireland.ie/digital-magazine-archive/</a></div>
<div></div>', 'Did you know that Changing Ireland is available in 310 public libraries – and university libraries for the record – across the country?', 'https://changingireland.ie/wp-content/uploads/2026/02/Did-you-know-that-Changing-Ireland-is-available-in-310-public-libraries-and-university-libraries-for-the-record-across-the-country.png', '', '[{"slug":"editors-picks","title":"Editor''s Picks"}]', '[{"slug":"library-service","title":"Library Service"}]', '', 256074, 1, '2026-02-13T01:00:56Z', '2026-06-25T11:54:58Z', '2026-02-13T01:00:56Z')
