INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('New National Community Cafés Action Group hopes for €1m support', 'new-national-community-cafes-action-group-hopes-for-e1m-support', '<p>The group represents 27 community cafés in ten counties and in July it visited Leinster House to officially launch an impact report.</p>
<p>Community cafes operate as independent social enterprises offering services to communities that would otherwise not be available.</p>
<p>They help to train and upskill local people, help with integration (for a great example from Tralee, see page 26) and they introduce people to community centres where they may then avail of other services and supports. They help people experiencing food poverty and today community cafes are busier than ever.</p>
<p>The action group has called for the establishment of a dedicated support scheme to help cover operational costs for their members.</p>
<p>The budget for the Department of Rural and Community Development includes “enhanced supports for a wide range of community development initiatives such as volunteering, and supports for the community and voluntary sector – with €23.1 million in funding available for this area. In addition, €5 million in funding is available for social innovation, social enterprise, and philanthropy.”</p>
<p>The action group, led by The Cottage in Loughmore, Co. Tipperary, hope some of this funding will be allocated to their request for approximately €1 million to support the 27 cafes.</p>
<p>There are of course many more community cafes that may also require support.</p>
<blockquote><p><a href="https://changingireland.ie/theres-a-different-world-out-there-that-no-one-talks-about/">St Munchin&#8217;s: &#8216;There’s a different world out there no one talks about&#8217;</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“St Munchin’s: ‘There’s a different world out there no one talks about’” — Changing Ireland" src="https://changingireland.ie/theres-a-different-world-out-there-that-no-one-talks-about/embed/#?secret=wWUtE34UKT#?secret=rLqZoEyBjD" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>', 'While a census of community cafes is unavailable, there certainly are hundreds of them across the country – and they are struggling to keep prices low and stay operational. The National Community Cafés Action Group is a new group, formed in January, and it has been lobbying the government for funding.', 'https://changingireland.ie/wp-content/uploads/2025/12/Ruth-Smith-PPN-coordinator-and-Mary-Fogarty-co-founder-and-manager-of-The-Cottage-Loughmore-with-the-impact-report.jpg', '', '[{"slug":"community-finance","title":"Community Finance"}]', '[{"slug":"community-cafe","title":"community café"}]', '', 255869, 1, '2025-12-11T02:49:27Z', '2025-12-11T03:13:36Z', '2025-12-11T02:49:27Z')
